package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen1Test {

    @Test
    public void testAbbreviate_NullString() {
        assertNull(WordUtils.abbreviate(null, 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_EmptyString() {
        assertEquals("", WordUtils.abbreviate("", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_UpperIsNegativeOne() {
        // upper = -1 sets upper to str.length()
        // index of space is -1, upper == str.length, so no appendToEnd
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, -1, "..."));
    }

    @Test
    public void testAbbreviate_UpperGreaterThanLength() {
        // upper > length sets upper to length
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, 50, "..."));
    }

    @Test
    public void testAbbreviate_UpperLessThanLower() {
        // upper < lower sets upper to lower
        // str="abc", lower=2, upper=1 -> upper becomes 2. 
        // index of space is -1. upper (2) != length (3), so append "..."
        assertEquals("ab...", WordUtils.abbreviate("abc", 2, 1, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInString() {
        // index == -1
        // upper < length, so appendToEnd
        assertEquals("Hel...", WordUtils.abbreviate("Hello", 0, 3, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceAndUpperEqualsLength() {
        // index == -1, upper == length, no appendToEnd
        assertEquals("Hello", WordUtils.abbreviate("Hello", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_SpaceAfterUpper() {
        // index > upper
        // "Hello World", lower=0, upper=3. index of space is 5. 5 > 3.
        // result: substring(0, 3) + "..."
        assertEquals("Hel...", WordUtils.abbreviate("Hello World", 0, 3, "..."));
    }

    @Test
    public void testAbbreviate_SpaceWithinUpper() {
        // index <= upper (but not -1)
        // "Hello World", lower=0, upper=6. index of space is 5. 5 <= 6.
        // result: substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 6, "..."));
    }

    @Test
    public void testAbbreviate_NullAppendToEnd() {
        // index == -1, upper < length, appendToEnd is null -> StringUtils.defaultString(null) is ""
        assertEquals("Hel", WordUtils.abbreviate("Hello", 0, 3, null));
    }

    @Test
    public void testAbbreviate_SpaceAtLowerBoundary() {
        // index == lower
        // "Hello World", lower=5, upper=10. index is 5. 5 <= 10.
        // result: substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 5, 10, "..."));
    }
}
